<div class="page-heading"><h1>Jadwal Saya</h1><p>Sesi daring, pertemuan tatap muka, dan tautan kelas untuk pelatihan Anda. Seluruh waktu menggunakan WIB.</p></div>
<?php $sessions=rows("SELECT s.*,p.title program_title,i.name instructor_name FROM training_sessions s JOIN registrations r ON r.batch_id=s.batch_id JOIN enrollments en ON en.registration_id=r.id JOIN training_batches b ON b.id=s.batch_id JOIN training_programs p ON p.slug=b.program_slug LEFT JOIN instructors i ON i.id=s.instructor_id WHERE r.user_id=? AND r.status='approved' AND en.status IN ('active','completed') ORDER BY s.starts_at",[$uid]);$calendarEvents=array_map(fn($s)=>['date'=>substr($s['starts_at'],0,10),'title'=>$s['title'],'url'=>'#session-'.$s['id']],$sessions);require __DIR__.'/../components/calendar.php';if(!$sessions)emptyState('Belum ada sesi terjadwal','Sesi akan ditampilkan setelah admin menerbitkan jadwal untuk kelas Anda.','portal.php?view=training','Lihat kelas'); ?>
<div class="stack"><?php foreach($sessions as $session): ?><article class="panel" id="session-<?= (int)$session['id'] ?>"><span class="badge"><?= e(strtoupper($session['method'])) ?></span><h2 style="margin-top:16px"><?= e($session['title']) ?></h2><p class="muted"><?= e($session['program_title']) ?></p><dl class="meta-list"><div><dt>Waktu (WIB)</dt><dd><?= e($session['starts_at'].' — '.$session['ends_at']) ?></dd></div><div><dt>Instruktur</dt><dd><?= e($session['instructor_name']?:'Belum diumumkan') ?></dd></div><div><dt>Lokasi</dt><dd><?= e($session['location']?:'Lihat informasi kelas daring') ?></dd></div></dl><?php if($url=safeUrl($session['meeting_url'])): ?><a class="btn" href="<?= e($url) ?>" target="_blank" rel="noopener noreferrer">Masuk ke sesi daring</a><?php endif; ?></article><?php endforeach; ?></div>
